// Settings → Figure grammar (OF-BLD-014 §6.1): the written definition of the
// grammar. Each figure drawn over a labelled sample, and the encoding legend.
// The sample is generated by `demo.py --prototype` into
// src/data/figureSamples.json; its first field, and this page, say it is one.
import type { ExtractionRecord } from '@/data/types';
import samples from '@/data/figureSamples.json';
import { Callout } from '@/components/ui';
import { CeilingGap, EncodingLegend, EvidenceStrip, Frontier } from '@/components/figures';

const records = samples.strip.records as unknown as ExtractionRecord[];

export function FiguresSection() {
  return (
    <div className="space-y-4" data-testid="figure-gallery">
      <Callout kind="warn" title="Sample values">
        {samples._sample}
      </Callout>
      <section>
        <h2 className="font-medium text-reading mb-1.5">The marks</h2>
        <p className="text-body text-ink-soft mb-2">
          The kind of thing decides the mark: a measurement or a record is a point, a computed limit a rule line, a computed
          curve a line. Provenance decides shape, fill and dash, so a figure reads the same in greyscale. A filled point
          always stands for an observed value.
        </p>
        <EncodingLegend />
      </section>
      <EvidenceStrip
        title="What has been reported for this field, and by whom?"
        records={records}
        unit={samples.strip.unit}
        quantity={samples.strip.quantity}
        groupBy="organism"
        csvName="sample-evidence-strip"
      />
      <CeilingGap
        title="How far is each reported yield from the most the network allows?"
        records={records}
        unit={samples.strip.unit}
        quantity={samples.strip.quantity}
        ceilings={samples.strip.rules.map((r) => ({ value: r.value, model: r.label }))}
        csvName="sample-ceiling-gap"
      />
      <Frontier
        title="How much product can a growing cell make?"
        points={samples.frontier.points}
        growthUnit={samples.frontier.growthUnit}
        productUnit={samples.frontier.productUnit}
        productLabel={samples.frontier.productLabel}
        model={samples.frontier.model}
        csvName="sample-frontier"
      />
    </div>
  );
}
